-- 校验：执行后各阶段词数（FIND_IN_SET 口径）
SELECT '中考' AS 阶段, COUNT(*) AS 词数 FROM dict_word WHERE FIND_IN_SET('zhongkao', levels)
UNION ALL SELECT '高考', COUNT(*) FROM dict_word WHERE FIND_IN_SET('gaokao', levels)
UNION ALL SELECT '四级', COUNT(*) FROM dict_word WHERE FIND_IN_SET('cet4', levels)
UNION ALL SELECT '六级', COUNT(*) FROM dict_word WHERE FIND_IN_SET('cet6', levels);
